  // A case whose pm4py error names hash-seed dependent operands compares
  // the error's class.
  const auto error_class = [](const std::string& shown) {
    if (!shown.starts_with("error: ")) return shown;
    return "error-class: " + shown.substr(7, shown.find(':', 7) - 7);
  };
  for (const auto& c : cases) {
    auto shown = outcome(client, c.name, c.content, c.shape, c.kind, c.fields);
    if (c.expected.starts_with("error-class: ")) shown = error_class(shown);
    check(c.label + " (" + c.shape + ")", shown, c.expected);
  }

  ::kill(server, SIGTERM);
  int status = 0;
  ::waitpid(server, &status, 0);
  if (g_failures) {
    std::cerr << g_failures << " check(s) failed\n";
    return 1;
  }
  std::cout << "review HB server checks passed\n";
  return 0;
